package com.travelbird.ai.entity;
import jakarta.persistence.*;import lombok.*;
@Entity @Table(name="ai_preview_places",uniqueConstraints={@UniqueConstraint(name="uk_ai_preview_place_global",columnNames={"preview_id","place_id"}),@UniqueConstraint(name="uk_ai_preview_day_order",columnNames={"preview_day_id","visit_order"})}) @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class AiPreviewPlace{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="preview_place_id") private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="preview_id",nullable=false) private AiTripPreview preview;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="preview_day_id",nullable=false) private AiPreviewDay day;@Column(name="place_id",nullable=false) private Long placeId;@Column(name="visit_order",nullable=false) private int visitOrder;@Column(nullable=false,length=100) private String reason;public AiPreviewPlace(Long placeId,int order,String reason){this.placeId=placeId;visitOrder=order;this.reason=reason;}void attach(AiTripPreview p,AiPreviewDay d){preview=p;day=d;}public void relocate(AiPreviewDay target,int order){day.getPlaces().remove(this);day=target;visitOrder=order;target.getPlaces().add(this);}public void stageOrder(){visitOrder+=1000;}}

